using System.IO.Compression;
using System.Data;
using System.Security.Cryptography;
using System.Text;
using System.Xml.Linq;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.DataProtection.KeyManagement;
using Microsoft.AspNetCore.DataProtection.Repositories;
using Microsoft.AspNetCore.HttpOverrides;
using Microsoft.Data.SqlClient;
using UniversityDemo.Notifications;
using UniversityDemo.Documents;

var b=WebApplication.CreateBuilder(args);
var cs=b.Configuration.GetConnectionString("SqlServer")??throw new InvalidOperationException("Falta conexión SQL.");
b.Services.AddDataProtection().SetApplicationName("UniversityDemo");
b.Services.Configure<KeyManagementOptions>(o=>o.XmlRepository=new SqlKeyRepository(cs));
b.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.Cookie.Name="UniversityDemo.Session";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Lax;o.Cookie.SecurePolicy=b.Environment.IsProduction()?CookieSecurePolicy.Always:CookieSecurePolicy.SameAsRequest;o.SlidingExpiration=true;o.Events.OnRedirectToLogin=c=>{c.Response.StatusCode=401;return Task.CompletedTask;};o.Events.OnRedirectToAccessDenied=c=>{c.Response.StatusCode=403;return Task.CompletedTask;};});
b.Services.AddAuthorization();
b.Services.AddNotificationSystem(cs,b.Configuration);
b.Services.AddSingleton<IOrderInvoiceStorage,SqlOrderInvoiceStorage>();
var app=b.Build();app.UseForwardedHeaders(new ForwardedHeadersOptions{ForwardedHeaders=ForwardedHeaders.XForwardedFor|ForwardedHeaders.XForwardedProto});app.UseAuthentication();app.UseAuthorization();
if(b.Configuration.GetValue<bool>("Database:CreateIfMissing"))await Db.Init(cs,true);
app.Use(async(context,next)=>
{
    if(context.Request.Path=="/api/orders"&&context.Request.Method=="POST"&&!(context.User.IsInRole("Admin")||context.User.IsInRole("Seller")))
    {
        context.Response.StatusCode=403;
        return;
    }
    await next();
});

app.MapPost("/api/auth/login",async(Login x,HttpContext h)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();await using var q=new SqlCommand("select Id,PasswordHash,Role,Active,isnull(SellerCode,''),isnull(ApprovalArea,'') from Users where UserName=@u",c);q.Parameters.AddWithValue("@u",x.UserName.Trim());await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync()||!r.GetBoolean(3)||!Passwords.Verify(x.Password,r.GetString(1)))return Results.Unauthorized();var claims=new[]{new System.Security.Claims.Claim("uid",r.GetInt32(0).ToString()),new System.Security.Claims.Claim(System.Security.Claims.ClaimTypes.Name,x.UserName),new System.Security.Claims.Claim(System.Security.Claims.ClaimTypes.Role,r.GetString(2)),new System.Security.Claims.Claim("seller_code",r.GetString(4)),new System.Security.Claims.Claim("approval_area",r.GetString(5))};await h.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new System.Security.Claims.ClaimsPrincipal(new System.Security.Claims.ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme)));return Results.Ok(new{user=x.UserName,role=r.GetString(2),sellerCode=r.GetString(4),approvalArea=r.GetString(5)});}).AllowAnonymous();
app.MapPost("/api/auth/logout",async(HttpContext h)=>{await using(var c=new SqlConnection(cs)){await c.OpenAsync();await using var cmd=new SqlCommand("update PushDevices set Active=0 where UserId=@u and ContinueAfterLogout=0",c);cmd.Parameters.AddWithValue("@u",int.Parse(h.User.FindFirst("uid")!.Value));await cmd.ExecuteNonQueryAsync();}await h.SignOutAsync();return Results.NoContent();}).RequireAuthorization();
app.MapGet("/api/auth/me",(HttpContext h)=>Results.Ok(new{id=int.Parse(h.User.FindFirst("uid")!.Value),user=h.User.Identity!.Name,role=h.User.FindFirst(System.Security.Claims.ClaimTypes.Role)!.Value,sellerCode=h.User.FindFirst("seller_code")?.Value??"",approvalArea=h.User.FindFirst("approval_area")?.Value??""})).RequireAuthorization();
app.MapNotificationSystem();

app.MapGet("/api/notifications",async(HttpContext h,string? category,bool? unread)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();var uid=int.Parse(h.User.FindFirst("uid")!.Value);var reviewer=h.User.IsInRole("Admin")||h.User.IsInRole("Approver");await using var cmd=new SqlCommand("select top 100 n.Id,n.Type,n.Title,n.Message,n.CreatedAt,convert(bit,case when r.NotificationId is null then 0 else 1 end),isnull(n.ActionUrl,'') from Notifications n left join NotificationReads r on r.NotificationId=n.Id and r.UserId=@uid left join NotificationPreferences p on p.UserId=@uid and p.Category=n.Type where isnull(p.Enabled,1)=1 and ((n.Audience='All' and (@seller=0 or n.Type in ('stock','system'))) or (n.Audience='Admin' and @reviewer=1) or n.TargetUserId=@uid or exists(select 1 from NotificationRecipients nr where nr.NotificationId=n.Id and nr.UserId=@uid)) and (@category='' or n.Type=@category) and (@unread=0 or r.NotificationId is null) order by n.CreatedAt desc,n.Id desc",c);cmd.Parameters.AddWithValue("@uid",uid);cmd.Parameters.AddWithValue("@reviewer",reviewer);cmd.Parameters.AddWithValue("@seller",h.User.IsInRole("Seller"));cmd.Parameters.AddWithValue("@category",category??"");cmd.Parameters.AddWithValue("@unread",unread==true);return Results.Ok(await Read(cmd,r=>new{id=r.GetInt32(0),type=r.GetString(1),title=r.GetString(2),message=r.GetString(3),createdAt=r.GetDateTime(4),isRead=r.GetBoolean(5),actionUrl=r.GetString(6)}));}).RequireAuthorization();
app.MapPut("/api/notifications/{id:int}/read",async(int id,HttpContext h)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();await using var cmd=new SqlCommand("if exists(select 1 from Notifications where Id=@id) and not exists(select 1 from NotificationReads where NotificationId=@id and UserId=@uid) insert NotificationReads(NotificationId,UserId) values(@id,@uid)",c);cmd.Parameters.AddWithValue("@id",id);cmd.Parameters.AddWithValue("@uid",int.Parse(h.User.FindFirst("uid")!.Value));await cmd.ExecuteNonQueryAsync();return Results.NoContent();}).RequireAuthorization();
app.MapPut("/api/notifications/read-all",async(HttpContext h)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();var uid=int.Parse(h.User.FindFirst("uid")!.Value);var reviewer=h.User.IsInRole("Admin")||h.User.IsInRole("Approver");await using var cmd=new SqlCommand("insert NotificationReads(NotificationId,UserId) select n.Id,@uid from Notifications n where ((n.Audience='All' and (@seller=0 or n.Type in ('stock','system'))) or (n.Audience='Admin' and @reviewer=1) or n.TargetUserId=@uid or exists(select 1 from NotificationRecipients nr where nr.NotificationId=n.Id and nr.UserId=@uid)) and not exists(select 1 from NotificationReads r where r.NotificationId=n.Id and r.UserId=@uid)",c);cmd.Parameters.AddWithValue("@uid",uid);cmd.Parameters.AddWithValue("@reviewer",reviewer);cmd.Parameters.AddWithValue("@seller",h.User.IsInRole("Seller"));await cmd.ExecuteNonQueryAsync();return Results.NoContent();}).RequireAuthorization();

app.MapGet("/api/products",async(string? q)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();await using var cmd=new SqlCommand("select Code,Description,Size,Pack,Stock,UnitPrice,StockUnits from Products where InCurrentStock=1 and StockUnits>0 and (@q='' or Code like @like or Description like @like) order by Description,Code",c);cmd.Parameters.AddWithValue("@q",q??"");cmd.Parameters.AddWithValue("@like","%"+(q??"")+"%");return Results.Ok(await Read(cmd,r=>new{code=r.GetString(0),description=r.GetString(1),size=r.GetString(2),pack=r.GetInt32(3),stock=r.GetDecimal(4),unitPrice=r.GetDecimal(5),stockUnits=r.GetDecimal(6)}));}).RequireAuthorization();
app.MapGet("/api/stock/products",async()=>{await using var c=new SqlConnection(cs);await c.OpenAsync();await using var cmd=new SqlCommand("select top 2000 Code,Description,Size,Pack,Stock,isnull(TotalStock,0),UpdatedAt from Products where InCurrentStock=1 order by Description,Code",c);return Results.Ok(await Read(cmd,r=>new{code=r.GetString(0),description=r.GetString(1),size=r.GetString(2),pack=r.GetInt32(3),stock=r.GetDecimal(4),totalStock=r.GetDecimal(5),updatedAt=DateTime.SpecifyKind(r.GetDateTime(6),DateTimeKind.Utc)}));}).RequireAuthorization(new AuthorizeAttribute{Roles="Admin,Seller"});
app.MapGet("/api/clients",async(string? q,HttpContext h)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();await using var cmd=new SqlCommand("select top 100 Id,Code,Name,Ruc,FiscalAddress,DeliveryAddress,PaymentTerms from Clients where (@admin=1 or exists(select 1 from UserSellerCodes us where us.UserId=@uid and us.SellerCode=Clients.SellerCode)) and (@q='' or Code like @like or Name like @like or Ruc like @like) order by Name",c);cmd.Parameters.AddWithValue("@admin",h.User.IsInRole("Admin"));cmd.Parameters.AddWithValue("@uid",int.Parse(h.User.FindFirst("uid")!.Value));cmd.Parameters.AddWithValue("@q",q??"");cmd.Parameters.AddWithValue("@like","%"+(q??"")+"%");return Results.Ok(await Read(cmd,r=>new{id=r.GetInt32(0),code=r.GetString(1),name=r.GetString(2),ruc=r.GetString(3),fiscalAddress=r.GetString(4),deliveryAddress=r.GetString(5),paymentTerms=r.GetString(6)}));}).RequireAuthorization();
app.MapPost("/api/clients",async(Client x)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();await using var cmd=new SqlCommand("insert into Clients(Code,Name,Ruc,FiscalAddress,DeliveryAddress,PaymentTerms) output inserted.Id values(@c,@n,@r,@f,@d,@p)",c);cmd.Parameters.AddWithValue("@c",x.Code.Trim());cmd.Parameters.AddWithValue("@n",x.Name.Trim());cmd.Parameters.AddWithValue("@r",x.Ruc.Trim());cmd.Parameters.AddWithValue("@f",x.FiscalAddress??"");cmd.Parameters.AddWithValue("@d",x.DeliveryAddress??"");cmd.Parameters.AddWithValue("@p",x.PaymentTerms??"");try{return Results.Created("/api/clients",new{id=(int)await cmd.ExecuteScalarAsync()!});}catch(SqlException e)when(e.Number is 2601 or 2627){return Results.Conflict(new{message="Código o RUC ya registrado."});}}).RequireAuthorization(new AuthorizeAttribute{Roles="Admin"});

app.MapPost("/api/stock/import",async(IFormFile file,HttpContext h)=>
{
    if(file.Length==0)return Results.BadRequest(new{message="El archivo está vacío."});
    List<ProductRow> rows;try{await using var stream=file.OpenReadStream();rows=Xlsx.Read(stream);}catch(InvalidDataException e){return Results.BadRequest(new{message=e.Message});}catch(Exception){return Results.BadRequest(new{message="No se pudo leer el Excel. Verifica que sea un archivo .xlsx válido y que conserve los encabezados originales."});}
    await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();
    try{await using(var clear=new SqlCommand("update Products set InCurrentStock=0,Stock=0,StockUnits=0,TotalStock=0",c,tx)){await clear.ExecuteNonQueryAsync();}foreach(var p in rows){await using var cmd=new SqlCommand("merge Products as t using(values(@c,@d,@s,@p,@perseo,@units,@total)) as v(Code,Description,Size,Pack,Stock,StockUnits,TotalStock) on t.Code=v.Code when matched then update set Description=v.Description,Size=v.Size,Pack=v.Pack,Stock=v.Stock,StockUnits=v.StockUnits,TotalStock=v.TotalStock,InCurrentStock=1,UpdatedAt=sysutcdatetime() when not matched then insert(Code,Description,Size,Pack,Stock,StockUnits,TotalStock,InCurrentStock) values(v.Code,v.Description,v.Size,v.Pack,v.Stock,v.StockUnits,v.TotalStock,1);",c,tx);cmd.Parameters.AddWithValue("@c",p.Code);cmd.Parameters.AddWithValue("@d",p.Description);cmd.Parameters.AddWithValue("@s",p.Size);cmd.Parameters.AddWithValue("@p",p.Pack);cmd.Parameters.AddWithValue("@perseo",p.Perseo);cmd.Parameters.AddWithValue("@units",p.Perseo*p.Pack);cmd.Parameters.AddWithValue("@total",p.Total);await cmd.ExecuteNonQueryAsync();}await using(var notice=new SqlCommand("insert into Notifications(Type,Title,Message,Audience,ActorUserId) values('stock','Stock actualizado',@message,'All',@actor)",c,tx)){notice.Parameters.AddWithValue("@message",$"{h.User.Identity!.Name} reemplazó el catálogo con {rows.Count:N0} productos del almacén PERSEO.");notice.Parameters.AddWithValue("@actor",int.Parse(h.User.FindFirst("uid")!.Value));await notice.ExecuteNonQueryAsync();}await tx.CommitAsync();return Results.Ok(new{imported=rows.Count,warehouse="PERSEO",perseoBoxes=rows.Sum(x=>x.Perseo),totalBoxes=rows.Sum(x=>x.Total),replaced=true});}catch{await tx.RollbackAsync();return Results.BadRequest(new{message="El archivo fue leído, pero no se pudo reemplazar el inventario. No se guardó ningún cambio."});}
}).RequireAuthorization(new AuthorizeAttribute{Roles="Admin"}).DisableAntiforgery();
app.MapPost("/api/orders",async(Order x,HttpContext h)=>
{
    if(x.Items.Count==0)return Results.BadRequest(new{message="Agrega al menos un producto."});
    if(x.Items.Any(i=>i.Quantity<=0||i.Quantity!=decimal.Truncate(i.Quantity)||(i.SaleType!="Unidad"&&i.SaleType!="Caja")))return Results.BadRequest(new{message="Las cantidades deben ser enteras y positivas y el tipo debe ser Unidad o Caja."});
    await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);
    try
    {
        var userId=int.Parse(h.User.FindFirst("uid")!.Value);var accountCode=x.SellerCode?.Trim();
        if(string.IsNullOrWhiteSpace(accountCode))throw new InvalidOperationException("Selecciona el código de vendedor para generar el correlativo.");
        if(!h.User.IsInRole("Admin")){await using var allowed=new SqlCommand("select count(*) from UserSellerCodes where UserId=@u and SellerCode=@c",c,tx);allowed.Parameters.AddWithValue("@u",userId);allowed.Parameters.AddWithValue("@c",accountCode);if((int)(await allowed.ExecuteScalarAsync())! == 0)throw new InvalidOperationException("Ese código de vendedor no está asignado a tu cuenta.");}
        accountCode=new string(accountCode.Where(ch=>char.IsLetterOrDigit(ch)||ch=='-'||ch=='_').ToArray()).ToUpperInvariant();
        var prepared=new List<(OrderItem Item,int Pack,decimal Units)>();
        foreach(var i in x.Items){await using var product=new SqlCommand("select Pack from Products with(updlock,holdlock) where Code=@c",c,tx);product.Parameters.AddWithValue("@c",i.ProductCode);var packValue=await product.ExecuteScalarAsync();if(packValue is null)throw new InvalidOperationException($"Producto {i.ProductCode} no encontrado.");var pack=(int)packValue;prepared.Add((i,pack,i.Quantity*(i.SaleType=="Caja"?pack:1)));}
        foreach(var group in prepared.GroupBy(v=>v.Item.ProductCode,StringComparer.OrdinalIgnoreCase)){var units=group.Sum(v=>v.Units);await using var reserve=new SqlCommand("update Products set StockUnits=StockUnits-@units,Stock=(StockUnits-@units)/Pack,UpdatedAt=sysutcdatetime() where Code=@code and StockUnits>=@units;if @@rowcount=0 throw 50001,'Stock insuficiente',1;",c,tx);reserve.Parameters.AddWithValue("@code",group.Key);reserve.Parameters.AddWithValue("@units",units);await reserve.ExecuteNonQueryAsync();}
        var now=DateTime.UtcNow;await using var next=new SqlCommand("declare @n int;select @n=isnull(max(SequenceNo),0)+1 from Orders with(updlock,holdlock) where SellerCode=@code and SequenceYear=@y and SequenceMonth=@m;select @n",c,tx);next.Parameters.AddWithValue("@code",accountCode);next.Parameters.AddWithValue("@y",now.Year);next.Parameters.AddWithValue("@m",now.Month);var sequence=(int)(await next.ExecuteScalarAsync())!;var number=$"{accountCode}-{now:MM-yyyy}-{sequence:0000}";
        await using var head=new SqlCommand("insert into Orders(Number,ClientId,SellerId,ClientName,ClientCode,ClientRuc,FiscalAddress,DeliveryAddress,DeliveryNotes,PaymentTerms,SellerCode,SequenceYear,SequenceMonth,SequenceNo) output inserted.Id values(@n,@c,@s,@cn,@cc,@cr,@f,@d,@o,@p,@sc,@y,@m,@seq)",c,tx);head.Parameters.AddWithValue("@n",number);head.Parameters.AddWithValue("@c",x.ClientId);head.Parameters.AddWithValue("@s",userId);head.Parameters.AddWithValue("@cn",x.ClientName??"");head.Parameters.AddWithValue("@cc",x.ClientCode??"");head.Parameters.AddWithValue("@cr",x.ClientRuc??"");head.Parameters.AddWithValue("@f",x.FiscalAddress??"");head.Parameters.AddWithValue("@d",x.DeliveryAddress??"");head.Parameters.AddWithValue("@o",x.DeliveryNotes??"");head.Parameters.AddWithValue("@p",x.PaymentTerms??"");head.Parameters.AddWithValue("@sc",accountCode);head.Parameters.AddWithValue("@y",now.Year);head.Parameters.AddWithValue("@m",now.Month);head.Parameters.AddWithValue("@seq",sequence);var oid=(int)(await head.ExecuteScalarAsync())!;
        foreach(var v in prepared){await using var line=new SqlCommand("insert into OrderItems(OrderId,ProductCode,Quantity,UnitPrice,SaleType,Pack,QuantityUnits) values(@o,@c,@q,@p,@t,@pack,@units)",c,tx);line.Parameters.AddWithValue("@o",oid);line.Parameters.AddWithValue("@c",v.Item.ProductCode);line.Parameters.AddWithValue("@q",v.Item.Quantity);line.Parameters.AddWithValue("@p",v.Item.UnitPrice);line.Parameters.AddWithValue("@t",v.Item.SaleType);line.Parameters.AddWithValue("@pack",v.Pack);line.Parameters.AddWithValue("@units",v.Units);await line.ExecuteNonQueryAsync();}
        await using(var notice=new SqlCommand("insert into Notifications(Type,Title,Message,Audience,ActorUserId,ActionUrl,DeduplicationKey) values('order','Nueva orden de pedido',@message,'Admin',@actor,@url,@key)",c,tx)){notice.Parameters.AddWithValue("@message",$"Pedido {number} registrado y pendiente de aprobación.");notice.Parameters.AddWithValue("@actor",userId);notice.Parameters.AddWithValue("@url",$"/?orderNumber={Uri.EscapeDataString(number)}");notice.Parameters.AddWithValue("@key",$"order:{oid}:created");await notice.ExecuteNonQueryAsync();}
        await tx.CommitAsync();return Results.Created($"/api/orders/{oid}",new{id=oid,number});
    }
    catch(Exception e){await tx.RollbackAsync();var message=e.Message.Contains("Stock insuficiente")?"Stock insuficiente: la suma de cajas y unidades supera la disponibilidad.":e is InvalidOperationException?e.Message:"No se pudo emitir el pedido.";return Results.BadRequest(new{message});}
}).RequireAuthorization();
app.MapGet("/api/orders",async(int? userId,HttpContext h)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();var admin=h.User.IsInRole("Admin");var approver=h.User.IsInRole("Approver");var current=int.Parse(h.User.FindFirst("uid")!.Value);await using var cmd=new SqlCommand("select top 500 o.Id,o.Number,o.CreatedAt,c.Name,u.UserName,isnull(o.SellerCode,''),(select sum(Quantity*UnitPrice) from OrderItems where OrderId=o.Id) Total,o.Status,isnull((select Decision from OrderApprovals where OrderId=o.Id and ApprovalArea='Alfredo'),''),isnull((select Decision from OrderApprovals where OrderId=o.Id and ApprovalArea='Credits'),'') from Orders o join Clients c on c.Id=o.ClientId join Users u on u.Id=o.SellerId where (@all=1 or o.SellerId=@current) and (@filter is null or o.SellerId=@filter) order by o.Id desc",c);cmd.Parameters.AddWithValue("@all",admin||approver);cmd.Parameters.AddWithValue("@current",current);cmd.Parameters.AddWithValue("@filter",admin&&userId.HasValue?userId.Value:DBNull.Value);return Results.Ok(await Read(cmd,r=>new{id=r.GetInt32(0),number=r.GetString(1),createdAt=r.GetDateTime(2),client=r.GetString(3),seller=r.GetString(4),sellerCode=r.GetString(5),total=r.GetDecimal(6),status=r.GetString(7),alfredoApproval=r.GetString(8),creditsApproval=r.GetString(9)}));}).RequireAuthorization();
app.MapGet("/api/orders/{id:int}",async(int id,HttpContext h)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();var admin=h.User.IsInRole("Admin");await using var head=new SqlCommand("select o.Id,o.Number,o.CreatedAt,c.Code,c.Name,c.Ruc,c.FiscalAddress,o.DeliveryAddress,o.PaymentTerms,o.DeliveryNotes,coalesce(nullif(o.SellerCode,''),u.UserName) from Orders o join Clients c on c.Id=o.ClientId join Users u on u.Id=o.SellerId where o.Id=@id and o.Status='Accepted' and (@a=1 or o.SellerId=@s)",c);head.Parameters.AddWithValue("@id",id);head.Parameters.AddWithValue("@a",admin);head.Parameters.AddWithValue("@s",int.Parse(h.User.FindFirst("uid")!.Value));await using var r=await head.ExecuteReaderAsync();if(!await r.ReadAsync())return Results.BadRequest(new{message="La orden solo puede imprimirse después de las dos aprobaciones."});var header=new{id=r.GetInt32(0),number=r.GetString(1),createdAt=r.GetDateTime(2),clientCode=r.GetString(3),client=r.GetString(4),ruc=r.GetString(5),fiscalAddress=r.GetString(6),deliveryAddress=r.GetString(7),paymentTerms=r.GetString(8),deliveryNotes=r.GetString(9),seller=r.GetString(10)};await r.CloseAsync();await using var lines=new SqlCommand("select i.ProductCode,p.Description,i.Quantity,i.UnitPrice,i.Quantity*i.UnitPrice Amount from OrderItems i join Products p on p.Code=i.ProductCode where i.OrderId=@id order by i.Id",c);lines.Parameters.AddWithValue("@id",id);var items=await Read(lines,x=>new{productCode=x.GetString(0),description=x.GetString(1),quantity=x.GetDecimal(2),unitPrice=x.GetDecimal(3),amount=x.GetDecimal(4)});return Results.Ok(new{header.id,header.number,header.createdAt,header.clientCode,header.client,header.ruc,header.fiscalAddress,header.deliveryAddress,header.paymentTerms,header.deliveryNotes,header.seller,items,total=items.Sum(x=>x.amount)});}).RequireAuthorization();
app.MapGet("/api/orders/{id:int}/review",async(int id,HttpContext h)=>{await using var c=new SqlConnection(cs);await c.OpenAsync();var all=h.User.IsInRole("Admin")||h.User.IsInRole("Approver");var uid=int.Parse(h.User.FindFirst("uid")!.Value);await using var head=new SqlCommand("select o.Id,o.Number,o.CreatedAt,c.Code,c.Name,c.Ruc,c.FiscalAddress,o.DeliveryAddress,o.PaymentTerms,o.DeliveryNotes,coalesce(nullif(o.SellerCode,''),u.UserName),u.UserName,o.Status,isnull((select Decision from OrderApprovals where OrderId=o.Id and ApprovalArea='Alfredo'),''),isnull((select Decision from OrderApprovals where OrderId=o.Id and ApprovalArea='Credits'),'') from Orders o join Clients c on c.Id=o.ClientId join Users u on u.Id=o.SellerId where o.Id=@id and (@all=1 or o.SellerId=@uid)",c);head.Parameters.AddWithValue("@id",id);head.Parameters.AddWithValue("@all",all);head.Parameters.AddWithValue("@uid",uid);await using var r=await head.ExecuteReaderAsync();if(!await r.ReadAsync())return Results.NotFound();var header=new{id=r.GetInt32(0),number=r.GetString(1),createdAt=r.GetDateTime(2),clientCode=r.GetString(3),client=r.GetString(4),ruc=r.GetString(5),fiscalAddress=r.GetString(6),deliveryAddress=r.GetString(7),paymentTerms=r.GetString(8),deliveryNotes=r.GetString(9),sellerCode=r.GetString(10),seller=r.GetString(11),status=r.GetString(12),alfredoApproval=r.GetString(13),creditsApproval=r.GetString(14)};await r.CloseAsync();await using var lines=new SqlCommand("select i.ProductCode,p.Description,p.Size,i.Quantity,i.UnitPrice,i.Quantity*i.UnitPrice Amount from OrderItems i join Products p on p.Code=i.ProductCode where i.OrderId=@id order by i.Id",c);lines.Parameters.AddWithValue("@id",id);var items=await Read(lines,x=>new{productCode=x.GetString(0),description=x.GetString(1),size=x.GetString(2),quantity=x.GetDecimal(3),unitPrice=x.GetDecimal(4),amount=x.GetDecimal(5)});return Results.Ok(new{header.id,header.number,header.createdAt,header.clientCode,header.client,header.ruc,header.fiscalAddress,header.deliveryAddress,header.paymentTerms,header.deliveryNotes,header.sellerCode,header.seller,header.status,header.alfredoApproval,header.creditsApproval,items,total=items.Sum(x=>x.amount)});}).RequireAuthorization();
app.MapPost("/api/orders/{id:int}/decision",async(int id,ApprovalInput x,HttpContext h)=>{var area=h.User.FindFirst("approval_area")?.Value??"";if(!h.User.IsInRole("Approver")||(area!="Alfredo"&&area!="Credits"))return Results.Forbid();var decision=x.Decision=="Approved"?"Approved":x.Decision=="Rejected"?"Rejected":"";if(decision=="")return Results.BadRequest(new{message="Decisión inválida."});await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();try{await using var state=new SqlCommand("select Status from Orders with(updlock,holdlock) where Id=@id",c,tx);state.Parameters.AddWithValue("@id",id);var status=(string?)await state.ExecuteScalarAsync();if(status is null)return Results.NotFound();if(status!="Pending")return Results.BadRequest(new{message="La orden ya fue resuelta."});await using(var save=new SqlCommand("if exists(select 1 from OrderApprovals where OrderId=@id and ApprovalArea=@area) throw 50005,'Ya decidiste esta orden',1;insert OrderApprovals(OrderId,ApprovalArea,ApproverUserId,Decision) values(@id,@area,@uid,@decision)",c,tx)){save.Parameters.AddWithValue("@id",id);save.Parameters.AddWithValue("@area",area);save.Parameters.AddWithValue("@uid",int.Parse(h.User.FindFirst("uid")!.Value));save.Parameters.AddWithValue("@decision",decision);await save.ExecuteNonQueryAsync();}if(decision=="Rejected"){await using var restore=new SqlCommand("update p set p.Stock=p.Stock+i.Quantity from Products p join OrderItems i on i.ProductCode=p.Code where i.OrderId=@id;update Orders set Status='Annulled',StockRestored=1 where Id=@id and StockRestored=0",c,tx);restore.Parameters.AddWithValue("@id",id);await restore.ExecuteNonQueryAsync();}else{await using var accept=new SqlCommand("if (select count(*) from OrderApprovals where OrderId=@id and Decision='Approved' and ApprovalArea in('Alfredo','Credits'))=2 update Orders set Status='Accepted' where Id=@id",c,tx);accept.Parameters.AddWithValue("@id",id);await accept.ExecuteNonQueryAsync();}await using(var notice=new SqlCommand("insert Notifications(Type,Title,Message,Audience,ActorUserId,TargetUserId,ActionUrl,DeduplicationKey) select case when Status='Annulled' then 'rejection' else 'approval' end,case when Status='Accepted' then 'Pedido aprobado' when Status='Annulled' then 'Pedido rechazado' when @area='Alfredo' then 'Crédito pendiente' else 'Aprobación registrada' end,case when Status='Accepted' then concat('Pedido ',Number,' aprobado y listo para facturación.') when Status='Annulled' then concat('Pedido ',Number,' rechazado.') when @area='Alfredo' then concat('Pedido ',Number,' pendiente de aprobación de crédito.') else concat('Pedido ',Number,' continúa pendiente de aprobación.') end,'Admin',@uid,SellerId,concat('/?orderNumber=',Number),concat('approval:',Id,':',@area,':',@decision) from Orders where Id=@id",c,tx)){notice.Parameters.AddWithValue("@id",id);notice.Parameters.AddWithValue("@area",area);notice.Parameters.AddWithValue("@decision",decision);notice.Parameters.AddWithValue("@uid",int.Parse(h.User.FindFirst("uid")!.Value));await notice.ExecuteNonQueryAsync();}await tx.CommitAsync();return Results.Ok(new{saved=true});}catch(Exception e){await tx.RollbackAsync();return Results.BadRequest(new{message=e.Message.Contains("Ya decidiste")?"Ya registraste tu decisión para esta orden.":"No se pudo registrar la decisión."});}}).RequireAuthorization(new AuthorizeAttribute{Roles="Approver"});
