    await using var c=new SqlConnection(cs);await c.OpenAsync();await using var cmd=new SqlCommand("insert into Sellers(Code,Name,Division,Active,UpdatedAt) values(@c,@n,@d,1,sysutcdatetime())",c);cmd.Parameters.AddWithValue("@c",code);cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@d",x.Division??"");
