    await using var cmd=new SqlCommand("insert into Clients(Code,Name,Ruc,FiscalAddress,DeliveryAddress,PaymentTerms,SellerCode) values(@c,@n,@r,@f,@d,@p,nullif(@s,''))",c);cmd.Parameters.AddWithValue("@c",code);cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@r",ruc);cmd.Parameters.AddWithValue("@f",x.FiscalAddress??"");cmd.Parameters.AddWithValue("@d",x.DeliveryAddress??x.FiscalAddress??"");cmd.Parameters.AddWithValue("@p",x.PaymentTerms??"");cmd.Parameters.AddWithValue("@s",seller);
    try{await cmd.ExecuteNonQueryAsync();return Results.Ok(new{saved=true});}catch(SqlException e)when(e.Number is 2601 or 2627){return Results.Conflict(new{message="Ya existe un cliente con ese código o R.U.C."});}
}).RequireAuthorization();
