    if(!h.User.IsInRole("Admin")){await using var access=new SqlCommand("select count(*) from Clients c where c.Id=@id and exists(select 1 from UserSellerCodes us where us.UserId=@u and us.SellerCode=c.SellerCode) and exists(select 1 from UserSellerCodes us where us.UserId=@u and us.SellerCode=@s)",c);access.Parameters.AddWithValue("@id",id);access.Parameters.AddWithValue("@u",int.Parse(h.User.FindFirst("uid")!.Value));access.Parameters.AddWithValue("@s",seller);if((int)(await access.ExecuteScalarAsync())! == 0)return Results.Forbid();}
