app.MapPost("/api/entities/import", async (IFormFile file,bool? validateOnly) =>
{
    if (file.Length == 0) return Results.BadRequest(new { message = "Archivo vacío." });
    if(!file.FileName.EndsWith(".xlsx",StringComparison.OrdinalIgnoreCase))return Results.BadRequest(new{message="Selecciona un archivo Excel .xlsx."});
    List<EntityRow> rows;try{await using var stream=file.OpenReadStream();rows=EntityXlsx.Read(stream);}catch(InvalidDataException e){return Results.BadRequest(new{message=e.Message});}catch(Exception){return Results.BadRequest(new{message="No se pudo leer el Excel. Verifica que conserve el formato de DOC INFO."});}
    if(rows.Count==0)return Results.BadRequest(new{message="El archivo no contiene clientes válidos."});
    static string Cut(string? value,int length)=>string.IsNullOrWhiteSpace(value)?"":value.Trim()[..Math.Min(value.Trim().Length,length)];
    var duplicateClientCodes=rows.GroupBy(x=>Cut(x.Code,30),StringComparer.OrdinalIgnoreCase).Count(g=>g.Count()>1);
    var clients=rows.GroupBy(x=>Cut(x.Code,30),StringComparer.OrdinalIgnoreCase).Select(g=>g.Last()).ToList();
    var sellers=rows.Where(x=>!string.IsNullOrWhiteSpace(x.SellerCode)).GroupBy(x=>Cut(x.SellerCode,30),StringComparer.OrdinalIgnoreCase).Select(g=>g.LastOrDefault(x=>!string.IsNullOrWhiteSpace(x.SellerName))??g.Last()).ToList();
    if(validateOnly==true)return Results.Ok(new{valid=true,clients=clients.Count,sellers=sellers.Count,duplicateClientCodes,withoutSeller=clients.Count(x=>string.IsNullOrWhiteSpace(x.SellerCode)),withoutRuc=clients.Count(x=>string.IsNullOrWhiteSpace(x.Ruc))});
    await using var c = new SqlConnection(cs);
    await c.OpenAsync();
    await using var tx = (SqlTransaction)await c.BeginTransactionAsync();
    try
    {
        var usedRucs=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);await using(var existing=new SqlCommand("select Ruc,Code from Clients",c,tx))await using(var reader=await existing.ExecuteReaderAsync()){while(await reader.ReadAsync())usedRucs[reader.GetString(0)]=reader.GetString(1);}
        static string FallbackRuc(string code)=>"SIN-"+Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(code)))[..16];
        var sellerTable=new DataTable();sellerTable.Columns.Add("Code",typeof(string));sellerTable.Columns.Add("Name",typeof(string));sellerTable.Columns.Add("Division",typeof(string));
        foreach(var seller in sellers){var code=Cut(seller.SellerCode,30);var name=Cut(string.IsNullOrWhiteSpace(seller.SellerName)?code:seller.SellerName,180);sellerTable.Rows.Add(code,name,Cut(seller.SellerName,120));}
        var clientTable=new DataTable();clientTable.Columns.Add("Code",typeof(string));clientTable.Columns.Add("Name",typeof(string));clientTable.Columns.Add("Ruc",typeof(string));clientTable.Columns.Add("Address",typeof(string));clientTable.Columns.Add("SellerCode",typeof(string));
        var withoutRuc=0;var withoutSeller=0;
        foreach(var entity in clients){var code=Cut(entity.Code,30);var ruc=Cut(entity.Ruc,20);if(ruc.Length==0||(usedRucs.TryGetValue(ruc,out var owner)&&!owner.Equals(code,StringComparison.OrdinalIgnoreCase))){ruc=FallbackRuc(code);withoutRuc++;}usedRucs[ruc]=code;var seller=Cut(entity.SellerCode,30);if(seller.Length==0)withoutSeller++;clientTable.Rows.Add(code,Cut(entity.Name,180),ruc,Cut(entity.Address,250),seller);}
        await using(var create=new SqlCommand("create table #ImportSellers(Code varchar(30) not null,Name nvarchar(180) not null,Division nvarchar(120) not null);create table #ImportClients(Code varchar(30) not null,Name nvarchar(180) not null,Ruc varchar(20) not null,Address nvarchar(250) not null,SellerCode varchar(30) not null);",c,tx)){await create.ExecuteNonQueryAsync();}
        using(var bulk=new SqlBulkCopy(c,SqlBulkCopyOptions.Default,tx)){bulk.DestinationTableName="#ImportSellers";bulk.BulkCopyTimeout=300;await bulk.WriteToServerAsync(sellerTable);}
        using(var bulk=new SqlBulkCopy(c,SqlBulkCopyOptions.Default,tx)){bulk.DestinationTableName="#ImportClients";bulk.BulkCopyTimeout=300;await bulk.WriteToServerAsync(clientTable);}
        await using(var mergeSellers=new SqlCommand("merge Sellers with(holdlock) as t using #ImportSellers as v on t.Code=v.Code when matched then update set Name=v.Name,Division=v.Division,Active=1,UpdatedAt=sysutcdatetime() when not matched then insert(Code,Name,Division,Active) values(v.Code,v.Name,v.Division,1);",c,tx)){mergeSellers.CommandTimeout=300;await mergeSellers.ExecuteNonQueryAsync();}
        await using(var mergeClients=new SqlCommand("merge Clients with(holdlock) as t using #ImportClients as v on t.Code=v.Code when matched then update set Name=v.Name,Ruc=v.Ruc,FiscalAddress=v.Address,DeliveryAddress=case when t.DeliveryAddress='' then v.Address else t.DeliveryAddress end,SellerCode=nullif(v.SellerCode,'') when not matched then insert(Code,Name,Ruc,FiscalAddress,DeliveryAddress,PaymentTerms,SellerCode) values(v.Code,v.Name,v.Ruc,v.Address,v.Address,'',nullif(v.SellerCode,''));",c,tx)){mergeClients.CommandTimeout=300;await mergeClients.ExecuteNonQueryAsync();}
        await tx.CommitAsync();return Results.Ok(new{clients=clients.Count,sellers=sellers.Count,duplicateClientCodes,withoutRuc,withoutSeller});
    }
    catch(Exception){await tx.RollbackAsync();return Results.BadRequest(new{message="No se pudo importar el archivo. Verifica códigos, R.U.C. y relaciones de vendedores."});}
}).RequireAuthorization(new AuthorizeAttribute { Roles = "Admin" }).DisableAntiforgery();
app.MapGet("/health",()=>Results.Ok(new{status="ready",runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,database="SQL Server"})).AllowAnonymous();

// Report timestamps come from persisted events; missing historical events remain null.
app.MapGet("/api/reports/orders",async(int? days,HttpContext h)=>
{
    var period=days is 7 or 30 or 90 ? days.Value : 30;
    var start=DateTime.UtcNow.AddHours(-5).Date.AddDays(1-period).AddHours(5);
    var uid=int.Parse(h.User.FindFirst("uid")!.Value);var all=!h.User.IsInRole("Seller");
    await using var c=new SqlConnection(cs);await c.OpenAsync();
    var sql="""
      select o.Id,o.Number,o.CreatedAt,coalesce(nullif(o.ClientName,''),c.Name),u.UserName,o.Status,o.FulfillmentStatus,
      coalesce((select sum(i.Quantity*i.UnitPrice) from OrderItems i where i.OrderId=o.Id),0),
      (select max(a.DecidedAt) from OrderApprovals a where a.OrderId=o.Id and a.Decision='Approved'),
      (select max(a.DecidedAt) from OrderApprovals a where a.OrderId=o.Id and a.ApproverUserId=@uid),
      (select top 1 a.Decision from OrderApprovals a where a.OrderId=o.Id and a.ApproverUserId=@uid),
      (select min(e.CreatedAt) from OrderFulfillmentEvents e where e.OrderId=o.Id and e.Status='Billed'),
      (select min(e.CreatedAt) from OrderFulfillmentEvents e where e.OrderId=o.Id and e.Status='Picking'),
      (select min(e.CreatedAt) from OrderFulfillmentEvents e where e.OrderId=o.Id and e.Status='Ready'),
      (select min(e.CreatedAt) from OrderFulfillmentEvents e where e.OrderId=o.Id and e.Status='InTransit'),
      (select min(e.CreatedAt) from OrderFulfillmentEvents e where e.OrderId=o.Id and e.Status='Delivered')
      from Orders o join Clients c on c.Id=o.ClientId join Users u on u.Id=o.SellerId
      where o.CreatedAt>=@start and o.CreatedAt<@end and (@all=1 or o.SellerId=@uid) order by o.CreatedAt desc
      """;
    await using var cmd=new SqlCommand(sql,c);cmd.Parameters.AddWithValue("@start",start);cmd.Parameters.AddWithValue("@end",start.AddDays(period));cmd.Parameters.AddWithValue("@uid",uid);cmd.Parameters.AddWithValue("@all",all);
    DateTime? date(SqlDataReader r,int i)=>r.IsDBNull(i)?null:DateTime.SpecifyKind(r.GetDateTime(i),DateTimeKind.Utc);
    return Results.Ok(await Read(cmd,r=>new{id=r.GetInt32(0),number=r.GetString(1),createdAt=DateTime.SpecifyKind(r.GetDateTime(2),DateTimeKind.Utc),client=r.GetString(3),seller=r.GetString(4),status=r.GetString(5),fulfillmentStatus=r.GetString(6),total=r.GetDecimal(7),approvedAt=date(r,8),myDecisionAt=date(r,9),myDecision=r.IsDBNull(10)?null:r.GetString(10),billedAt=date(r,11),pickingAt=date(r,12),readyAt=date(r,13),inTransitAt=date(r,14),deliveredAt=date(r,15)}));
}).RequireAuthorization();

app.MapGet("/api/workflow/orders",async(int? userId,HttpContext h)=>
{
    await using var c=new SqlConnection(cs);await c.OpenAsync();
    var all=h.User.IsInRole("Admin")||h.User.IsInRole("Approver")||h.User.IsInRole("Billing")||h.User.IsInRole("Warehouse");var current=int.Parse(h.User.FindFirst("uid")!.Value);
    var sql="""select top 500 o.Id,o.Number,o.CreatedAt,c.Name,u.UserName,isnull(o.SellerCode,''),(select sum(Quantity*UnitPrice) from OrderItems where OrderId=o.Id),o.Status,concat((select count(*) from OrderApprovals a where a.OrderId=o.Id and a.ApprovalArea in('Credits','Commercial') and a.Decision='Approved'),'/2'),isnull((select top 1 a.Decision from OrderApprovals a join Users me on me.Id=@current where a.OrderId=o.Id and a.ApprovalArea=me.ApprovalArea),''),o.FulfillmentStatus,convert(bit,case when o.Status='Annulled' and exists(select 1 from OrderRejections r where r.OrderId=o.Id) then 1 else 0 end) from Orders o join Clients c on c.Id=o.ClientId join Users u on u.Id=o.SellerId where (@all=1 or o.SellerId=@current) and (@filter is null or o.SellerId=@filter) order by o.Id desc""";
    await using var cmd=new SqlCommand(sql,c);cmd.Parameters.AddWithValue("@all",all);cmd.Parameters.AddWithValue("@current",current);cmd.Parameters.AddWithValue("@filter",h.User.IsInRole("Admin")&&userId.HasValue?userId.Value:DBNull.Value);
    return Results.Ok(await Read(cmd,r=>new{id=r.GetInt32(0),number=r.GetString(1),createdAt=r.GetDateTime(2),client=r.GetString(3),seller=r.GetString(4),sellerCode=r.GetString(5),total=r.GetDecimal(6),status=r.GetString(7),approvalSummary=r.GetString(8),currentUserDecision=r.GetString(9),fulfillmentStatus=r.GetString(10),rejected=r.GetBoolean(11)}));
}).RequireAuthorization();

app.MapGet("/api/workflow/orders/{id:int}",async(int id,HttpContext h)=>
{
