        var decision=action is "Approved" or "ApproveObserved"?"Approved":"Rejected";await using(var save=new SqlCommand("merge OrderApprovals as t using(values(@id,@area,@uid,@decision))v(OrderId,ApprovalArea,UserId,Decision) on t.OrderId=v.OrderId and t.ApprovalArea=v.ApprovalArea when matched then update set ApproverUserId=v.UserId,Decision=v.Decision,DecidedAt=sysutcdatetime() when not matched then insert(OrderId,ApprovalArea,ApproverUserId,Decision) values(v.OrderId,v.ApprovalArea,v.UserId,v.Decision);",c,tx)){save.Parameters.AddWithValue("@id",id);save.Parameters.AddWithValue("@area",area);save.Parameters.AddWithValue("@uid",uid);save.Parameters.AddWithValue("@decision",decision);await save.ExecuteNonQueryAsync();}
