        if(action=="Rejected"){await using var rejection=new SqlCommand("if exists(select 1 from OrderRejections where OrderId=@id) update OrderRejections set RejectedByUserId=@uid,Reason=@reason,CreatedAt=sysutcdatetime(),FinalizedAt=null,FinalizedByUserId=null where OrderId=@id else insert OrderRejections(OrderId,RejectedByUserId,Reason) values(@id,@uid,@reason)",c,tx);rejection.Parameters.AddWithValue("@id",id);rejection.Parameters.AddWithValue("@uid",uid);rejection.Parameters.AddWithValue("@reason",reason);await rejection.ExecuteNonQueryAsync();}
        var cancel=area=="Commercial"&&action=="Rejected"||action=="ConfirmRejection";if(cancel){await using var restore=new SqlCommand("update Orders set Status='Annulled',StockRestored=1 where Id=@id and StockRestored=0;if @@rowcount=1 begin;with restored as(select ProductCode,sum(QuantityUnits) Units from OrderItems where OrderId=@id group by ProductCode) update p set StockUnits=p.StockUnits+r.Units,Stock=(p.StockUnits+r.Units)/p.Pack,UpdatedAt=sysutcdatetime() from Products p join restored r on r.ProductCode=p.Code;end;update OrderRejections set FinalizedAt=sysutcdatetime(),FinalizedByUserId=@uid where OrderId=@id",c,tx);restore.Parameters.AddWithValue("@id",id);restore.Parameters.AddWithValue("@uid",uid);await restore.ExecuteNonQueryAsync();}else if(area=="Credits"&&action=="Rejected"){await using var observe=new SqlCommand("update Orders set Status='Observed' where Id=@id",c,tx);observe.Parameters.AddWithValue("@id",id);await observe.ExecuteNonQueryAsync();}else{await using var next=new SqlCommand("update Orders set Status=case when (select count(*) from OrderApprovals where OrderId=@id and ApprovalArea in('Credits','Commercial') and Decision='Approved')=2 then 'Accepted' else 'Pending' end where Id=@id",c,tx);next.Parameters.AddWithValue("@id",id);await next.ExecuteNonQueryAsync();}
        await using(var notice=new SqlCommand("declare @event bigint=(select max(Id) from OrderApprovalEvents where OrderId=@id);insert Notifications(Type,Title,Message,Audience,TargetUserId,ActorUserId,ActionUrl,DeduplicationKey) select case when Status in('Observed','Annulled') then 'rejection' else 'approval' end,case when Status='Observed' then 'Pedido observado' when Status='Annulled' then 'Pedido cancelado' when Status='Accepted' then 'Pedido aprobado' else 'Aprobación registrada' end,case when Status='Observed' then concat('Pedido ',Number,' observado por Créditos. Motivo: ',@reason) when Status='Annulled' then concat('Pedido ',Number,' cancelado. Motivo: ',coalesce(nullif(@reason,''),(select Reason from OrderRejections where OrderId=@id))) when Status='Accepted' then concat('Pedido ',Number,' aprobado y listo para facturación.') else concat('Pedido ',Number,' continúa pendiente de aprobación.') end,'User',SellerId,@uid,concat('/?orderNumber=',Number),concat('approval-event:',@event) from Orders where Id=@id",c,tx)){notice.Parameters.AddWithValue("@id",id);notice.Parameters.AddWithValue("@uid",uid);notice.Parameters.AddWithValue("@reason",reason);await notice.ExecuteNonQueryAsync();}
        await tx.CommitAsync();return Results.Ok(new{saved=true});
