        await using var beforeCmd=new SqlCommand("select ProductCode,Quantity,UnitPrice,SaleType,Pack,QuantityUnits from OrderItems where OrderId=@id for json path",c,tx);beforeCmd.Parameters.AddWithValue("@id",id);var beforeJson=(string?)await beforeCmd.ExecuteScalarAsync()??"[]";
        await using(var restore=new SqlCommand("with old as(select ProductCode,sum(QuantityUnits) Units from OrderItems where OrderId=@id group by ProductCode) update p set StockUnits=p.StockUnits+o.Units,Stock=(p.StockUnits+o.Units)/p.Pack,UpdatedAt=sysutcdatetime() from Products p join old o on o.ProductCode=p.Code",c,tx)){restore.Parameters.AddWithValue("@id",id);await restore.ExecuteNonQueryAsync();}
        await using(var clear=new SqlCommand("delete OrderItems where OrderId=@id",c,tx)){clear.Parameters.AddWithValue("@id",id);await clear.ExecuteNonQueryAsync();}
        foreach(var item in x.Items){await using var product=new SqlCommand("select Pack from Products with(updlock,holdlock) where Code=@code",c,tx);product.Parameters.AddWithValue("@code",item.ProductCode);var packValue=await product.ExecuteScalarAsync();if(packValue is null)throw new InvalidOperationException("Producto no encontrado.");var pack=(int)packValue;var units=item.Quantity*(item.SaleType=="Caja"?pack:1);await using var reserve=new SqlCommand("update Products set StockUnits=StockUnits-@units,Stock=(StockUnits-@units)/Pack,UpdatedAt=sysutcdatetime() where Code=@code and StockUnits>=@units;if @@rowcount=0 throw 50001,'Stock insuficiente',1;insert OrderItems(OrderId,ProductCode,Quantity,UnitPrice,SaleType,Pack,QuantityUnits) values(@id,@code,@quantity,@price,@type,@pack,@units)",c,tx);reserve.Parameters.AddWithValue("@id",id);reserve.Parameters.AddWithValue("@code",item.ProductCode);reserve.Parameters.AddWithValue("@quantity",item.Quantity);reserve.Parameters.AddWithValue("@price",item.UnitPrice);reserve.Parameters.AddWithValue("@type",item.SaleType);reserve.Parameters.AddWithValue("@pack",pack);reserve.Parameters.AddWithValue("@units",units);await reserve.ExecuteNonQueryAsync();}
