        await using(var notice=new SqlCommand("declare @event bigint=(select max(Id) from OrderApprovalEvents where OrderId=@id);insert Notifications(Type,Title,Message,Audience,TargetUserId,ActorUserId,ActionUrl,DeduplicationKey) select 'approval','Pedido modificado por Comercial',concat('El pedido ',Number,' fue modificado y requiere una nueva evaluación de Créditos.'),'User',SellerId,@uid,concat('/?orderNumber=',Number),concat('approval-event:',@event) from Orders where Id=@id",c,tx)){notice.Parameters.AddWithValue("@id",id);notice.Parameters.AddWithValue("@uid",uid);await notice.ExecuteNonQueryAsync();}
