app.MapPost("/api/workflow/orders/{id:int}/invoice",async(int id,IFormFile file,[Microsoft.AspNetCore.Mvc.FromForm]string invoiceNumber,bool? replace,HttpContext h,IOrderInvoiceStorage documents)=>
{
    if(!h.User.IsInRole("Billing"))return Results.Forbid();
    invoiceNumber=(invoiceNumber??"").Trim();if(invoiceNumber.Length<2||invoiceNumber.Length>60)return Results.BadRequest(new{message="Ingresa un número de factura válido."});
    if(file.Length==0||file.Length>15*1024*1024)return Results.BadRequest(new{message="El PDF es obligatorio y no debe superar 15 MB."});
    if(!string.Equals(Path.GetExtension(file.FileName),".pdf",StringComparison.OrdinalIgnoreCase))return Results.BadRequest(new{message="Solo se admite un archivo PDF."});
    byte[] data;await using(var input=file.OpenReadStream()){using var memory=new MemoryStream();await input.CopyToAsync(memory);data=memory.ToArray();}
    if(data.Length<5||data[0]!=0x25||data[1]!=0x50||data[2]!=0x44||data[3]!=0x46||data[4]!=0x2D)return Results.BadRequest(new{message="El archivo no contiene una firma PDF válida."});
    var uid=int.Parse(h.User.FindFirst("uid")!.Value);var hash=Convert.ToHexString(SHA256.HashData(data));
    await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable);
    try
    {
        await using var state=new SqlCommand("select Status,FulfillmentStatus,Number,SellerId from Orders with(updlock,holdlock) where Id=@id",c,tx);state.Parameters.AddWithValue("@id",id);await using var reader=await state.ExecuteReaderAsync();if(!await reader.ReadAsync()){await reader.CloseAsync();await tx.RollbackAsync();return Results.NotFound();}var orderStatus=reader.GetString(0);var fulfillment=reader.GetString(1);var number=reader.GetString(2);var seller=reader.GetInt32(3);await reader.CloseAsync();
        if(orderStatus!="Accepted")return Results.Conflict(new{message="El pedido todavía no está aprobado."});
        await using var current=new SqlCommand("select top 1 Id,FileHash from OrderInvoices where OrderId=@id and Status='Active'",c,tx);current.Parameters.AddWithValue("@id",id);await using var currentReader=await current.ExecuteReaderAsync();long? currentId=null;string? currentHash=null;if(await currentReader.ReadAsync()){currentId=currentReader.GetInt64(0);currentHash=currentReader.GetString(1);}await currentReader.CloseAsync();
        if(currentId.HasValue&&replace!=true)return Results.Conflict(new{message="El pedido ya tiene una factura activa."});
        if(currentHash==hash)return Results.Conflict(new{message="Ese mismo PDF ya está registrado en el pedido."});
        if(!currentId.HasValue&&fulfillment!="AwaitingBilling")return Results.Conflict(new{message="El pedido ya no está pendiente de facturación."});
        if(currentId.HasValue){await using var end=new SqlCommand("update OrderInvoices set Status='Replaced',EndedAt=sysutcdatetime(),EndedByUserId=@uid,EndReason='Reemplazo de factura' where Id=@current and Status='Active'",c,tx);end.Parameters.AddWithValue("@uid",uid);end.Parameters.AddWithValue("@current",currentId.Value);await end.ExecuteNonQueryAsync();}
        var(invoiceId,version)=await documents.SaveAsync(c,tx,id,invoiceNumber,file.FileName,data,hash,uid,h.RequestAborted);
        if(!currentId.HasValue){await using var update=new SqlCommand("update Orders set FulfillmentStatus='Billed' where Id=@id and FulfillmentStatus='AwaitingBilling';insert OrderFulfillmentEvents(OrderId,Status,ActorUserId) values(@id,'Billed',@uid)",c,tx);update.Parameters.AddWithValue("@id",id);update.Parameters.AddWithValue("@uid",uid);await update.ExecuteNonQueryAsync();}
        await using var notice=new SqlCommand("insert Notifications(Type,Title,Message,Audience,TargetUserId,ActorUserId,ActionUrl,DeduplicationKey) values('billing',case when @replacement=1 then 'Factura reemplazada' else 'Pedido facturado' end,case when @replacement=1 then concat('La factura del pedido ',@number,' fue reemplazada.') else concat('Tu pedido ',@number,' fue facturado. Factura ',@invoice,'.') end,'User',@seller,@uid,concat('/?orderNumber=',@number),concat('invoice:',@id,':',@version))",c,tx);notice.Parameters.AddWithValue("@replacement",currentId.HasValue);notice.Parameters.AddWithValue("@number",number);notice.Parameters.AddWithValue("@invoice",invoiceNumber);notice.Parameters.AddWithValue("@seller",seller);notice.Parameters.AddWithValue("@uid",uid);notice.Parameters.AddWithValue("@id",id);notice.Parameters.AddWithValue("@version",version);await notice.ExecuteNonQueryAsync();
        await tx.CommitAsync();return Results.Ok(new{id=invoiceId,version,invoiceNumber,saved=true});
    }
    catch(SqlException e){await tx.RollbackAsync();return Results.Conflict(new{message=e.Number is 2601 or 2627?"Ya existe una factura activa para este pedido.":"No se pudo guardar la factura."});}
}).RequireAuthorization(new AuthorizeAttribute{Roles="Billing"}).DisableAntiforgery();

