app.MapPost("/api/workflow/orders/{id:int}/fulfillment",async(int id,FulfillmentInput x,HttpContext h)=>
{
    var billing=h.User.IsInRole("Billing");var warehouse=h.User.IsInRole("Warehouse");
    if(billing)return Results.BadRequest(new{message="Adjunta el PDF y el número de factura para facturar el pedido."});if(!warehouse)return Results.Forbid();
    var uid=int.Parse(h.User.FindFirst("uid")!.Value);await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();
    try {
        await using var change=new SqlCommand("update Orders set FulfillmentStatus=@next output inserted.Number,inserted.SellerId where Id=@id and Status='Accepted' and ((@billing=1 and FulfillmentStatus='AwaitingBilling' and @next='Billed') or (@warehouse=1 and ((FulfillmentStatus='Billed' and @next='Picking') or (FulfillmentStatus='Picking' and @next='Ready') or (FulfillmentStatus='Ready' and @next='InTransit') or (FulfillmentStatus='InTransit' and @next='Delivered'))))",c,tx);
        change.Parameters.AddWithValue("@next",x.Status??"");change.Parameters.AddWithValue("@id",id);change.Parameters.AddWithValue("@billing",billing);change.Parameters.AddWithValue("@warehouse",warehouse);
        await using var r=await change.ExecuteReaderAsync();if(!await r.ReadAsync()){await r.CloseAsync();await tx.RollbackAsync();return Results.Conflict(new{message="El pedido no está disponible para este cambio de estado."});}var number=r.GetString(0);var seller=r.GetInt32(1);await r.CloseAsync();
        await using(var ev=new SqlCommand("insert OrderFulfillmentEvents(OrderId,Status,ActorUserId) values(@id,@status,@uid)",c,tx)){ev.Parameters.AddWithValue("@id",id);ev.Parameters.AddWithValue("@status",x.Status);ev.Parameters.AddWithValue("@uid",uid);await ev.ExecuteNonQueryAsync();}
        var (category,title,message)=x.Status switch {
            "Billed" => ("billing","Pedido facturado",$"Tu pedido {number} ya fue facturado."),
            "Picking" => ("order","Pedido en preparación",$"Tu pedido {number} está siendo preparado en almacén."),
            "Ready" => ("order","Pedido listo en almacén",$"Tu pedido {number} está preparado y listo para salir de almacén."),
            "InTransit" => ("order","Pedido en ruta",$"Tu pedido {number} está en ruta hacia su destino."),
            "Delivered" => ("order","Pedido entregado",$"Tu pedido {number} fue marcado como entregado."),
            _ => throw new InvalidOperationException("Estado de seguimiento inválido.")
        };
        await using(var notice=new SqlCommand("insert Notifications(Type,Title,Message,Audience,TargetUserId,ActorUserId,ActionUrl,DeduplicationKey) values(@type,@title,@message,'User',@seller,@actor,@url,@key)",c,tx)){notice.Parameters.AddWithValue("@type",category);notice.Parameters.AddWithValue("@title",title);notice.Parameters.AddWithValue("@message",message);notice.Parameters.AddWithValue("@seller",seller);notice.Parameters.AddWithValue("@actor",uid);notice.Parameters.AddWithValue("@url",$"/?orderNumber={Uri.EscapeDataString(number)}");notice.Parameters.AddWithValue("@key",$"fulfillment:{id}:{x.Status}");await notice.ExecuteNonQueryAsync();}
        await tx.CommitAsync();return Results.Ok(new{saved=true});
    }catch {await tx.RollbackAsync();throw;}
}).RequireAuthorization(new AuthorizeAttribute{Roles="Billing,Warehouse"});

