app.MapPut("/api/workflow/users/{id:int}",async(int id,UserUpdateInput x,HttpContext h)=>
{
    var codes=(x.SellerCodes??[]).Where(v=>!string.IsNullOrWhiteSpace(v)).Select(v=>v.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList();var role=x.Role is "Admin" or "Approver" or "Billing" or "Warehouse"?x.Role:"Seller";var area=role=="Approver"&&x.ApprovalArea is "Credits" or "Commercial"?x.ApprovalArea:"";
    if(string.IsNullOrWhiteSpace(x.UserName))return Results.BadRequest(new{message="El nombre de usuario es obligatorio."});if(!string.IsNullOrEmpty(x.Password)&&x.Password.Length<8)return Results.BadRequest(new{message="La nueva contraseña debe tener al menos 8 caracteres."});if(role=="Seller"&&codes.Count==0)return Results.BadRequest(new{message="Selecciona al menos un código de vendedor para esta cuenta."});if(role=="Approver"&&area=="")return Results.BadRequest(new{message="Selecciona la responsabilidad Créditos o Comercial."});
    var currentId=int.Parse(h.User.FindFirst("uid")!.Value);if(id==currentId&&(role!="Admin"||!x.Active))return Results.BadRequest(new{message="No puedes quitar tu propio perfil de administrador ni desactivar tu cuenta."});
    await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();
    try
    {
        if(role=="Seller"){await using var valid=new SqlCommand("select count(*) from Sellers where Active=1 and Code in (select value from openjson(@codes))",c,tx);valid.Parameters.AddWithValue("@codes",System.Text.Json.JsonSerializer.Serialize(codes));if((int)(await valid.ExecuteScalarAsync())! != codes.Count){await tx.RollbackAsync();return Results.BadRequest(new{message="Uno o más códigos de vendedor no existen o están inactivos."});}}
        if(role=="Approver"&&x.Active){await using var occupied=new SqlCommand("if exists(select 1 from Users where Id<>@id and Role='Approver' and ApprovalArea=@area and Active=1) throw 50008,'Responsabilidad ocupada',1",c,tx);occupied.Parameters.AddWithValue("@id",id);occupied.Parameters.AddWithValue("@area",area);await occupied.ExecuteNonQueryAsync();}
        await using(var update=new SqlCommand("update Users set UserName=@u,Role=@r,SellerCode=nullif(@legacy,''),ApprovalArea=nullif(@area,''),Active=@active,PasswordHash=case when @password='' then PasswordHash else @password end where Id=@id",c,tx)){update.Parameters.AddWithValue("@id",id);update.Parameters.AddWithValue("@u",x.UserName.Trim());update.Parameters.AddWithValue("@r",role);update.Parameters.AddWithValue("@legacy",role=="Seller"?codes.FirstOrDefault()??"":"");update.Parameters.AddWithValue("@area",area);update.Parameters.AddWithValue("@active",x.Active);update.Parameters.AddWithValue("@password",string.IsNullOrEmpty(x.Password)?"":Passwords.Hash(x.Password));if(await update.ExecuteNonQueryAsync()==0){await tx.RollbackAsync();return Results.NotFound();}}
        await using(var clear=new SqlCommand("delete UserSellerCodes where UserId=@id",c,tx)){clear.Parameters.AddWithValue("@id",id);await clear.ExecuteNonQueryAsync();}
        if(role=="Seller")foreach(var code in codes){await using var link=new SqlCommand("insert UserSellerCodes(UserId,SellerCode) values(@id,@code)",c,tx);link.Parameters.AddWithValue("@id",id);link.Parameters.AddWithValue("@code",code);await link.ExecuteNonQueryAsync();}
        await tx.CommitAsync();return Results.Ok(new{saved=true});
    }
    catch(SqlException e){await tx.RollbackAsync();return e.Number is 2601 or 2627?Results.Conflict(new{message="Ese nombre de usuario ya existe."}):Results.BadRequest(new{message="No se pudo actualizar el usuario."});}
}).RequireAuthorization(new AuthorizeAttribute{Roles="Admin"});

