static class Passwords{public static string Hash(string p){var salt=RandomNumberGenerator.GetBytes(16);var hash=Rfc2898DeriveBytes.Pbkdf2(p,salt,210000,HashAlgorithmName.SHA256,32);return Convert.ToBase64String(salt)+"."+Convert.ToBase64String(hash);}public static bool Verify(string p,string v){var a=v.Split('.');var salt=Convert.FromBase64String(a[0]);return CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(a[1]),Rfc2898DeriveBytes.Pbkdf2(p,salt,210000,HashAlgorithmName.SHA256,32));}}
