if col_length('Products','InCurrentStock') is null begin alter table Products add InCurrentStock bit null;exec('update Products set InCurrentStock=1 where InCurrentStock is null');alter table Products alter column InCurrentStock bit not null;alter table Products add constraint DF_Products_InCurrentStock default 1 for InCurrentStock;end;
