sealed class SqlKeyRepository(string connectionString):IXmlRepository{public IReadOnlyCollection<XElement> GetAllElements(){using var c=new SqlConnection(connectionString);c.Open();using var cmd=new SqlCommand("select Xml from DataProtectionKeys order by Id",c);using var r=cmd.ExecuteReader();var keys=new List<XElement>();while(r.Read())keys.Add(XElement.Parse(r.GetString(0)));return keys;}public void StoreElement(XElement element,string friendlyName){using var c=new SqlConnection(connectionString);c.Open();using var cmd=new SqlCommand("insert DataProtectionKeys(FriendlyName,Xml) values(@n,@x)",c);cmd.Parameters.AddWithValue("@n",friendlyName);cmd.Parameters.AddWithValue("@x",element.ToString(SaveOptions.DisableFormatting));cmd.ExecuteNonQuery();}}
record ProductRow(string Code,string Description,string Size,int Pack,decimal Perseo,decimal Total,bool Adjusted);
record EntityRow(string Code,string Ruc,string Name,string Address,string SellerCode,string SellerName);
static class Xlsx
{
    public static List<ProductRow> Read(Stream input)
    {
        using var z=new ZipArchive(input,ZipArchiveMode.Read,true);XNamespace n="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        var shared=z.GetEntry("xl/sharedStrings.xml") is{} se?XDocument.Load(se.Open()).Descendants(n+"si").Select(x=>string.Concat(x.Descendants(n+"t").Select(t=>t.Value))).ToList():[];
        var sheet=z.Entries.FirstOrDefault(e=>e.FullName.StartsWith("xl/worksheets/sheet")&&e.FullName.EndsWith(".xml"))??throw new InvalidDataException("El archivo no contiene una hoja de cálculo válida.");
        var doc=XDocument.Load(sheet.Open());var excelRows=doc.Descendants(n+"row").ToList();
        Dictionary<string,string> Cells(XElement row)=>row.Elements(n+"c").ToDictionary(c=>new string(((string?)c.Attribute("r")??"").TakeWhile(char.IsLetter).ToArray()),Value,StringComparer.OrdinalIgnoreCase);
        string Normalize(string value)=>new string(value.Trim().Normalize(NormalizationForm.FormD).Where(ch=>System.Globalization.CharUnicodeInfo.GetUnicodeCategory(ch)!=System.Globalization.UnicodeCategory.NonSpacingMark&&char.IsLetterOrDigit(ch)).Select(char.ToUpperInvariant).ToArray());
        var headerRow=excelRows.FirstOrDefault(row=>Cells(row).Values.Select(Normalize).Contains("CODIGO")&&Cells(row).Values.Select(Normalize).Contains("PERSEO"))??throw new InvalidDataException("No se encontraron los encabezados Código y PERSEO.");
        var headers=Cells(headerRow).ToDictionary(kv=>Normalize(kv.Value),kv=>kv.Key,StringComparer.OrdinalIgnoreCase);
        string Required(params string[] names){foreach(var name in names)if(headers.TryGetValue(Normalize(name),out var column))return column;throw new InvalidDataException($"Falta la columna requerida: {names[0]}.");}
        var codeCol=Required("Codigo","Código");var descriptionCol=Required("Descripcion","Descripción","Producto");var sizeCol=Required("Size","Presentacion");var packCol=Required("Pack");var perseoCol=Required("PERSEO");var totalCol=Required("TOTAL");
        decimal Number(string value){if(string.IsNullOrWhiteSpace(value))return 0;if(decimal.TryParse(value,System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out var number))return number;if(decimal.TryParse(value,System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.GetCultureInfo("es-PE"),out number))return number;throw new InvalidDataException($"Valor numérico inválido: {value}.");}
        var result=new List<ProductRow>();foreach(var row in excelRows.SkipWhile(r=>r!=headerRow).Skip(1)){var cells=Cells(row);string Get(string column)=>cells.TryGetValue(column,out var value)?value:"";var code=Get(codeCol).Trim();if(string.IsNullOrWhiteSpace(code))continue;var description=Get(descriptionCol).Trim();if(string.IsNullOrWhiteSpace(description))throw new InvalidDataException($"El producto {code} no tiene descripción.");var packValue=Number(Get(packCol));if(packValue<=0||packValue!=decimal.Truncate(packValue))throw new InvalidDataException($"El Pack de {code} debe ser un entero positivo.");var rawPerseo=Number(Get(perseoCol));var rawTotal=Number(Get(totalCol));var adjusted=rawPerseo<0||rawTotal<0;result.Add(new(code,description,Get(sizeCol).Trim(),(int)packValue,Math.Max(0,rawPerseo),Math.Max(0,rawTotal),adjusted));}
        if(result.Count==0)throw new InvalidDataException("El archivo no contiene productos para importar.");return result;
        string Value(XElement c){var raw=c.Element(n+"v")?.Value??string.Concat(c.Descendants(n+"t").Select(t=>t.Value));return (string?)c.Attribute("t")=="s"&&int.TryParse(raw,out var i)&&i>=0&&i<shared.Count?shared[i]:raw;}
    }
}
static class EntityXlsx
{
    public static List<EntityRow> Read(Stream input)
    {
        using var archive=new ZipArchive(input,ZipArchiveMode.Read,true);XNamespace ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        var shared=archive.GetEntry("xl/sharedStrings.xml") is{} sharedEntry?XDocument.Load(sharedEntry.Open()).Descendants(ns+"si").Select(x=>string.Concat(x.Descendants(ns+"t").Select(t=>t.Value))).ToList():[];
        var sheet=archive.Entries.FirstOrDefault(e=>e.FullName.StartsWith("xl/worksheets/sheet",StringComparison.OrdinalIgnoreCase)&&e.FullName.EndsWith(".xml",StringComparison.OrdinalIgnoreCase))??throw new InvalidDataException("El archivo no contiene una hoja de cálculo válida.");
        var excelRows=XDocument.Load(sheet.Open()).Descendants(ns+"row").ToList();
        string Value(XElement cell){var raw=cell.Element(ns+"v")?.Value??string.Concat(cell.Descendants(ns+"t").Select(t=>t.Value));return (string?)cell.Attribute("t")=="s"&&int.TryParse(raw,out var index)&&index>=0&&index<shared.Count?shared[index]:raw;}
        Dictionary<string,string> Cells(XElement row)=>row.Elements(ns+"c").ToDictionary(cell=>new string(((string?)cell.Attribute("r")??"").TakeWhile(char.IsLetter).ToArray()),Value,StringComparer.OrdinalIgnoreCase);
        string Normalize(string value)=>new string(value.Trim().Normalize(NormalizationForm.FormD).Where(ch=>System.Globalization.CharUnicodeInfo.GetUnicodeCategory(ch)!=System.Globalization.UnicodeCategory.NonSpacingMark&&char.IsLetterOrDigit(ch)).Select(char.ToUpperInvariant).ToArray());
        var header=excelRows.FirstOrDefault(row=>{var cells=Cells(row);return cells.TryGetValue("A",out var a)&&Normalize(a)=="CODIGO"&&cells.TryGetValue("C",out var c)&&Normalize(c)=="RUC"&&cells.TryGetValue("D",out var d)&&Normalize(d).StartsWith("RAZON")&&cells.TryGetValue("G",out var g)&&Normalize(g)=="VENDEDOR"&&cells.TryGetValue("H",out var h)&&Normalize(h)=="VENDEDOR";})??throw new InvalidDataException("No se encontraron las columnas Código, R.U.C., Razón, Dirección y Vendedor del formato DOC INFO.");
        static string Clean(string? value)=>string.IsNullOrWhiteSpace(value)?"":value.Trim().Trim('"').Trim();
        var rows=new List<EntityRow>();foreach(var row in excelRows.SkipWhile(x=>x!=header).Skip(1)){var cells=Cells(row);string Get(string column)=>cells.TryGetValue(column,out var value)?Clean(value):"";var code=Get("A");var name=Get("D");if(code.Length==0||name.Length==0)continue;rows.Add(new(code,Get("C"),name,Get("E"),Get("G"),Get("H")));}
        if(rows.Count==0)throw new InvalidDataException("El archivo no contiene clientes para importar.");return rows;
    }
}
